DO $$ BEGIN IF (SELECT count(*) FROM archived)<>1 OR (SELECT replayed FROM archived) OR (SELECT count(*) FROM public.sales_opportunities WHERE archived_at IS NOT NULL)<>5 OR (SELECT count(*) FROM public.customer_requirements WHERE archived_at IS NOT NULL)<>5 OR (SELECT count(*) FROM public.sales_sample_archive_manifest_items)<>10 THEN RAISE EXCEPTION 'Archive did not atomically persist ten roots'; END IF; END $$;
DO $$ BEGIN IF NOT (SELECT replayed FROM public.archive_reviewed_sales_samples('[{"kind":"OPPORTUNITY","id":"104fb9e2-7f83-40f9-a295-64b37aa8c7ee","displayNumber":"OPPORTUNITY-2026-0006"},{"kind":"OPPORTUNITY","id":"becebb23-e0f2-4264-a78f-fda04275cade","displayNumber":"OPPORTUNITY-2026-0007"},{"kind":"OPPORTUNITY","id":"428d7d9e-25bf-4e98-94d5-416ea56155e3","displayNumber":"OPPORTUNITY-2026-0008"},{"kind":"OPPORTUNITY","id":"dc101dd9-89a2-4dad-9903-3b2301a97d3b","displayNumber":"OPPORTUNITY-2026-0009"},{"kind":"OPPORTUNITY","id":"d79f58c1-bbee-4940-9e67-88f267f5449b","displayNumber":"OPPORTUNITY-2026-0010"},{"kind":"REQUIREMENT","id":"aaabd18c-5885-45de-9e0e-da70d4ec491f","displayNumber":"CUSTOMER-2026-0003"},{"kind":"REQUIREMENT","id":"36cdc159-57c7-4568-a1b0-ec481f5d3d93","displayNumber":"CUSTOMER-2026-0004"},{"kind":"REQUIREMENT","id":"6aa2fc2f-eb75-48c2-a9de-d13008cf1c5c","displayNumber":"CUSTOMER-2026-0005"},{"kind":"REQUIREMENT","id":"2db48440-5424-4e5e-bb5b-01f203a7662f","displayNumber":"CUSTOMER-2026-0006"},{"kind":"REQUIREMENT","id":"e829dd82-381d-42ab-a808-62979e9156f4","displayNumber":"CUSTOMER-2026-0007"}]'::jsonb,'verified disposable samples','00000000-0000-4000-8000-000000000011')) THEN RAISE EXCEPTION 'Exact replay failed'; END IF; BEGIN PERFORM * FROM public.archive_reviewed_sales_samples('[]','changed','00000000-0000-4000-8000-000000000011'); RAISE EXCEPTION 'Conflicting replay accepted'; EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'Archive request key conflicts%' THEN RAISE; END IF; END; END $$;
INSERT INTO public.sales_nda_records VALUES ('104fb9e2-7f83-40f9-a295-64b37aa8c7ee');
DO $$ BEGIN BEGIN PERFORM * FROM public.restore_reviewed_sales_samples((SELECT manifest_id FROM archived),'restore with drift','00000000-0000-4000-8000-000000000012'); RAISE EXCEPTION 'Dependency-drift restore accepted'; EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'Restore is blocked by dependency drift%' THEN RAISE; END IF; END; IF (SELECT count(*) FROM public.sales_sample_archive_manifests WHERE action='RESTORE')<>0 THEN RAISE EXCEPTION 'Blocked restore left a receipt'; END IF; END $$;
DELETE FROM public.sales_nda_records;
CREATE TEMP TABLE restored AS SELECT * FROM public.restore_reviewed_sales_samples((SELECT manifest_id FROM archived),'restore verified disposable samples','00000000-0000-4000-8000-000000000012');
DO $$ BEGIN IF (SELECT replayed FROM restored) OR (SELECT count(*) FROM public.sales_opportunities WHERE archived_at IS NOT NULL)<>0 OR (SELECT count(*) FROM public.customer_requirements WHERE archived_at IS NOT NULL)<>0 OR (SELECT count(*) FROM public.sales_sample_archive_audit_events)<>2 THEN RAISE EXCEPTION 'Restore did not atomically restore roots and audit'; END IF; END $$;
ROLLBACK;
